<script setup>
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {useDemo} from '../../stores/demo.js'
import PageHeader from '../../components/PageHeader.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import TaskCards from './visual/TaskCards.vue'
const store=useDemo(),route=useRoute(),search=ref(''),queue=ref('unassigned')
watch(()=>route.query.queue,value=>{queue.value=['unassigned','mine','drafts','all'].includes(value)?value:'unassigned'},{immediate:true})
const available=computed(()=>store.selectEvents({search:search.value}).map(e=>{const reports=store.visibleRecords('reports').filter(r=>r.eventId===e.id&&['1B','2','3B'].includes(r.type)),drafts=reports.filter(r=>r.status==='draft').sort((a,b)=>(b.revision||0)-(a.revision||0));return{...e,reports,draft:drafts[0],investigator:store.state.users.find(u=>u.id===e.investigatorId)?.name||'Unassigned'}}))
const matches=(e,key)=>key==='unassigned'?e.status!=='draft'&&!e.investigatorId:key==='mine'?e.status!=='draft'&&e.investigatorId===store.currentUser.value?.id:key==='drafts'?!!e.draft:true
const tasks=computed(()=>[{id:'unassigned',label:'Incoming / unassigned',icon:'move_to_inbox'},{id:'mine',label:'Assigned to me',icon:'assignment_ind'},{id:'drafts',label:'Draft reports',icon:'edit_document'},{id:'all',label:'All incidents',icon:'folder_open'}].map(q=>({...q,count:available.value.filter(e=>matches(e,q.id)).length})))
const rows=computed(()=>available.value.filter(e=>matches(e,queue.value)))
const queueHelp=computed(()=>({unassigned:'Choose an incoming incident to assign an investigator and start its report.',mine:'Continue incidents assigned to your account. Other scoped incidents remain available under All incidents.',drafts:'Open a saved draft to continue preparing its initial, progress or final report.',all:'Search all incidents available in your account and office scope.'}[queue.value]))
const columns=[{name:'ref',label:'Incident',field:'ref',align:'left',sortable:true},{name:'investigator',label:'Investigator',field:'investigator',align:'left',sortable:true},{name:'stage',label:'Next report task',field:'reports',align:'left'},{name:'asOf',label:'Latest as-of / target',field:'reports',align:'left'},{name:'status',label:'Review status',field:'status',align:'left'},{name:'actions',label:'',field:'id'}]
</script>
<template><div class="page-wrap investigations-page"><PageHeader title="Investigations" subtitle="Choose an incident, continue a report, or follow up its cases and actions."><template #actions><q-btn outline no-caps label="Cases" icon="gavel" to="/admin/cases" v-if="store.can('enforce')"/><q-btn outline no-caps label="Follow-up actions" icon="task_alt" to="/admin/actions"/><q-btn color="primary" no-caps label="Create an output" icon="description" to="/admin/reports"/></template></PageHeader>
 <TaskCards :tasks="tasks" :selected="queue" @select="queue=$event" class="q-mb-lg"/>
 <div class="panel toolbar-row q-mb-md"><q-input v-model="search" outlined dense clearable label="Search incident or vessel" style="min-width:250px"><template #prepend><q-icon name="search"/></template></q-input><q-space/><span class="muted">{{rows.length}} incidents</span><q-btn flat dense no-caps label="Incident register" to="/admin/incidents"/></div>
 <div class="queue-explanation q-mb-md"><q-icon name="info_outline" color="primary" size="18px"/><span>{{queueHelp}}</span></div>
 <q-card flat class="investigation-table"><q-table flat :rows="rows" :columns="columns" row-key="id" :pagination="{rowsPerPage:10}" no-data-label="No incidents match this task. Choose another task or clear the search."><template #body-cell-ref="p"><q-td :props="p"><router-link class="record-link" :to="`/admin/investigations/${p.row.id}`">{{p.row.ref}}</router-link><div class="muted">{{p.row.type}} · {{p.row.dateUnknown?'Date unknown':p.row.date||'Date unknown'}}</div><div class="text-caption muted">{{p.row.vessels?.map(v=>v.name).join(' / ')}}</div></q-td></template><template #body-cell-stage="p"><q-td :props="p"><template v-if="p.row.draft"><strong>Continue Form {{p.row.draft.type}}</strong><div class="muted">Draft revision {{p.row.draft.revision}}</div></template><template v-else-if="p.row.reports.some(r=>r.type==='3B'&&r.status==='issued')"><strong>Final report issued</strong><div class="muted">Follow up recommendations</div></template><template v-else-if="p.row.reports.length"><strong>Record the next update</strong><div class="muted">{{p.row.reports.filter(r=>r.status==='issued').length}} issued revisions</div></template><span v-else class="muted">Prepare an initial report</span></q-td></template><template #body-cell-asOf="p"><q-td :props="p">{{p.row.reports.map(r=>r.asOf||r.date).filter(Boolean).sort().reverse()[0]||'Not reported'}}<div class="muted">Target {{p.row.reports.find(r=>r.fields?.investigationDueDate)?.fields.investigationDueDate||'not assigned'}}</div></q-td></template><template #body-cell-status="p"><q-td :props="p"><StatusBadge :status="p.row.status"/></q-td></template><template #body-cell-actions="p"><q-td :props="p"><q-btn color="primary" :outline="!p.row.draft" :unelevated="!!p.row.draft" no-caps :label="p.row.draft?'Continue draft':'Workbench'" :to="{path:`/admin/investigations/${p.row.id}`,query:p.row.draft?{reportId:p.row.draft.id}:{}}"/><q-btn flat dense no-caps label="Incident" :to="`/admin/incidents/${p.row.id}`"/></q-td></template></q-table></q-card>
</div></template>
<style scoped>.investigation-table{background:var(--ss-card,#fff);border:.5px solid var(--ss-border,#e2e5ea);border-radius:10px;box-shadow:0 1px 3px #0000000d,0 1px 2px #00000005!important;min-width:0}.queue-explanation{display:flex;align-items:flex-start;gap:10px;color:var(--ss-muted,#64748b);padding:0 4px;line-height:1.6}.investigations-page :deep(.q-table__container){min-width:0;max-width:100%}.investigations-page :deep(.q-table td){white-space:normal}.investigations-page :deep(.q-table th){font-size:11px;color:#9ca3af;font-weight:500;letter-spacing:.05em;padding:12px 16px}.investigations-page :deep(.q-table td){padding:11px 16px;font-size:13px;border-bottom:.5px solid var(--ss-border,#f3f4f6)}@media(max-width:599px){.toolbar-row .q-field{min-width:0!important;width:100%}}
</style>
